cat > /tmp/q.ts <<'EOF'
import { Database } from "bun:sqlite";
const db = new Database("data/habit-tracker.db");
const habits = db.query("select id,name,archived_at from habits").all();
for (const h of habits) {
  const c = db.query("select count(*) as n from checkins where habit_id=?").get(h.id);
  console.log(h.name, "| archived:", h.archived_at, "| checkins:", c.n, "| id:", h.id);
}
EOF
bun /tmp/q.ts

